data=json.loads("\"diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\\nindex 70372f8..4a09fed 100644\\n--- a/skills/codex-delegate/scripts/relay.mjs\\n+++ b/skills/codex-delegate/scripts/relay.mjs\\n@@ -52,7 +52,8 @@\\n  * file must therefore also treat a non-zero exit with no file as a usage error.\\n  */\\n \\n-import { spawn, execFileSync } from \\\"node:child_process\\\";\\n+import { execFileSync } from \\\"node:child_process\\\";\\n+import { spawnCodex } from \\\"./spawn-codex.mjs\\\";\\n import { mkdirSync, writeFileSync, readFileSync, existsSync, appendFileSync } from \\\"node:fs\\\";\\n import { join, resolve, basename } from \\\"node:path\\\";\\n import { constants, tmpdir } from \\\"node:os\\\";\\n@@ -164,11 +165,7 @@ function timestamp() {\\n function buildArgv(opts, finalPath) {\\n   const argv = [\\\"exec\\\"];\\n   if (opts.resumeLast) argv.push(\\\"resume\\\", \\\"--last\\\");\\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\\n-  // args, so a temp path with spaces (C:\\\\Users\\\\First Last\\\\...) splits and the\\n-  // trailing \\\"-\\\" misparses (issue #3). Quote the only spaceable arg in argv.\\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\\n-  const outPath = process.platform === \\\"win32\\\" ? `\\\"${finalPath}\\\"` : finalPath;\\n+  const outPath = finalPath;\\n   argv.push(\\\"--json\\\", \\\"-o\\\", outPath);\\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\\n   // session's sandbox and working root, and we set the child process cwd below.\\n@@ -253,10 +250,18 @@ function reportUnavailable(writeResult, resultPath) {\\n \\n function dispatchToCodex(opts, brief, run, writeResult) {\\n   const argv = buildArgv(opts, run.finalPath);\\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\\n-  const child = spawn(\\\"codex\\\", argv, { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], shell: process.platform === \\\"win32\\\" });\\n+  let child;\\n+  try {\\n+    child = spawnCodex(argv, { cd: opts.cd });\\n+  } catch (err) {\\n+    const result = writeResult({\\n+      status: \\\"failed\\\", exitCode: 1, signal: null, threadId: null,\\n+      finalMessage: \\\"\\\", touchedFiles: gitTouchedFiles(opts.cd),\\n+      error: String(err && err.message ? err.message : err),\\n+    });\\n+    printSummary(result, run.resultPath);\\n+    process.exit(1);\\n+  }\\n \\n   let threadId = null;\\n   let stdoutBuf = \\\"\\\";\\ndiff --git a/skills/codex-delegate/scripts/spawn-codex.mjs b/skills/codex-delegate/scripts/spawn-codex.mjs\\nnew file mode 100644\\nindex 0000000..a84eeac\\n--- /dev/null\\n+++ b/skills/codex-delegate/scripts/spawn-codex.mjs\\n@@ -0,0 +1,32 @@\\n+/** Launch Codex without letting caller-controlled arguments become cmd syntax. */\\n+import { spawn } from \\\"node:child_process\\\";\\n+\\n+// A .cmd shim needs cmd.exe on Windows. cmd expands %VAR% and potentially\\n+// !VAR! even inside quotes, and caret/double quotes can alter parsing. Reject\\n+// these rather than accepting shell interpretation of a file path or model.\\n+export function quoteForCmd(value) {\\n+  const arg = String(value);\\n+  if (/[\\\\r\\\\n\\\"%!^]/u.test(arg)) {\\n+    throw new Error(\\\"unsupported Windows shell character in Codex argument\\\");\\n+  }\\n+  // Always quote each entire argument: whitespace and cmd operators such as\\n+  // &, |, <, >, ( and ) then remain part of that argument.\\n+  return `\\\"${arg}\\\"`;\\n+}\\n+\\n+export function codexSpawnSpec(argv, cd, platform = process.platform) {\\n+  if (platform !== \\\"win32\\\") {\\n+    return { command: \\\"codex\\\", args: argv, options: { cwd: cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"] } };\\n+  }\\n+  const commandLine = [\\\"codex\\\", ...argv].map(quoteForCmd).join(\\\" \\\");\\n+  return {\\n+    command: \\\"cmd.exe\\\",\\n+    args: [\\\"/d\\\", \\\"/s\\\", \\\"/c\\\", commandLine],\\n+    options: { cwd: cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], windowsHide: true },\\n+  };\\n+}\\n+\\n+export function spawnCodex(argv, { cd }) {\\n+  const spec = codexSpawnSpec(argv, cd);\\n+  return spawn(spec.command, spec.args, spec.options);\\n+}\\ndiff --git a/tests/codex-relay.integration.test.mjs b/tests/codex-relay.integration.test.mjs\\nnew file mode 100644\\nindex 0000000..140fa17\\n--- /dev/null\\n+++ b/tests/codex-relay.integration.test.mjs\\n@@ -0,0 +1,45 @@\\n+import test from 'node:test';\\n+import assert from 'node:assert/strict';\\n+import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, chmodSync, rmSync } from 'node:fs';\\n+import { tmpdir } from 'node:os';\\n+import { join, resolve } from 'node:path';\\n+import { spawnSync } from 'node:child_process';\\n+\\n+const relay = resolve('skills/codex-delegate/scripts/relay.mjs');\\n+\\n+test('relay keeps stdin, final message, events, and git touched files with spaces in paths', { skip: process.platform === 'win32' && 'POSIX fake executable' }, () => {\\n+  const root = mkdtempSync(join(tmpdir(), 'codex relay test '));\\n+  try {\\n+    const bin = join(root, 'bin');\\n+    const repo = join(root, 'repo with spaces');\\n+    const out = join(root, 'output with spaces');\\n+    mkdirSync(bin); mkdirSync(repo); mkdirSync(out);\\n+    const fake = join(bin, 'codex');\\n+    writeFileSync(fake, `#!/usr/bin/env node\\n+const fs = require('fs');\\n+const args = process.argv.slice(2);\\n+if (args[0] === '--version') { console.log('codex-cli 0.test'); process.exit(0); }\\n+const output = args[args.indexOf('-o') + 1];\\n+const input = fs.readFileSync(0, 'utf8');\\n+if (args.at(-1) !== '-' || input !== 'Say PING\\\\\\\\n') process.exit(7);\\n+fs.writeFileSync(output, 'PING_FROM_CODEX\\\\\\\\n');\\n+console.log(JSON.stringify({ type: 'thread.started', thread_id: 'test-thread' }));\\n+`);\\n+    chmodSync(fake, 0o755);\\n+    const init = spawnSync('git', ['init', '-q', repo], { encoding: 'utf8' });\\n+    assert.equal(init.status, 0, init.stderr);\\n+    writeFileSync(join(root, 'brief with spaces.txt'), 'Say PING\\\\n');\\n+    const result = spawnSync(process.execPath, [relay, '--cd', repo, '--brief', join(root, 'brief with spaces.txt'), '--out-dir', out, '--read-only'], {\\n+      cwd: repo, encoding: 'utf8', env: { ...process.env, PATH: `${bin}:${process.env.PATH}` },\\n+    });\\n+    assert.equal(result.status, 0, result.stderr + result.stdout);\\n+    const data = JSON.parse(readFileSync(join(out, 'result.json'), 'utf8'));\\n+    assert.equal(data.status, 'completed');\\n+    assert.equal(data.exitCode, 0);\\n+    assert.equal(data.finalMessage, 'PING_FROM_CODEX');\\n+    assert.equal(data.threadId, 'test-thread');\\n+    assert.deepEqual(data.touchedFiles, []);\\n+    assert.match(readFileSync(join(out, 'events.jsonl'), 'utf8'), /test-thread/);\\n+    assert.equal(readFileSync(join(out, 'final.txt'), 'utf8').trim(), 'PING_FROM_CODEX');\\n+  } finally { rmSync(root, { recursive: true, force: true }); }\\n+});\\ndiff --git a/tests/codex-spawn.test.mjs b/tests/codex-spawn.test.mjs\\nnew file mode 100644\\nindex 0000000..8a3f306\\n--- /dev/null\\n+++ b/tests/codex-spawn.test.mjs\\n@@ -0,0 +1,34 @@\\n+import test from 'node:test';\\n+import assert from 'node:assert/strict';\\n+import { codexSpawnSpec, quoteForCmd } from '../skills/codex-delegate/scripts/spawn-codex.mjs';\\n+\\n+test('POSIX preserves argv as individual tokens without a shell', () => {\\n+  const argv = ['exec', '--json', '-o', '/tmp/user with spaces/final.txt', '-s', 'read-only', '-'];\\n+  const spec = codexSpawnSpec(argv, '/work dir', 'linux');\\n+  assert.equal(spec.command, 'codex');\\n+  assert.deepEqual(spec.args, argv);\\n+  assert.equal(spec.options.cwd, '/work dir');\\n+  assert.equal(spec.options.shell, undefined);\\n+});\\n+\\n+test('Windows uses cmd shim with quoted output path and stdin sentinel', () => {\\n+  const argv = ['exec', '--json', '-o', String.raw`C:\\\\Users\\\\Mahmoud Sabry\\\\AppData\\\\Local\\\\Temp\\\\delegate-relay\\\\final.txt`, '-s', 'read-only', '-'];\\n+  const spec = codexSpawnSpec(argv, 'C:\\\\\\\\work', 'win32');\\n+  assert.equal(spec.command, 'cmd.exe');\\n+  assert.deepEqual(spec.args.slice(0, 3), ['/d', '/s', '/c']);\\n+  assert.equal(spec.args[3], ['codex', ...argv].map(quoteForCmd).join(' '));\\n+  assert.ok(spec.args[3].includes('\\\"C:\\\\\\\\Users\\\\\\\\Mahmoud Sabry\\\\\\\\AppData'));\\n+  assert.ok(spec.args[3].endsWith('\\\"-\\\"'));\\n+  assert.equal(spec.options.windowsHide, true);\\n+});\\n+\\n+test('Windows quotes shell operators as data', () => {\\n+  assert.equal(quoteForCmd('model & option'), '\\\"model & option\\\"');\\n+  assert.equal(quoteForCmd(''), '\\\"\\\"');\\n+});\\n+\\n+test('Windows rejects arguments that cmd could expand or reparse', () => {\\n+  for (const value of ['%PATH%', '!PATH!', 'a\\\" & echo injected', 'a^b', 'line\\\\nbreak', 'line\\\\rbreak']) {\\n+    assert.throws(() => quoteForCmd(value), /unsupported Windows shell character/);\\n+  }\\n+});\\n\"").encode('utf-8')
